class Solution {
public:
    int minEatingSpeed(vector<int>& piles, int h) {
        int low = 1, high = *max_element(piles.begin(), piles.end());
        int answer = high;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            long long hours = 0;
            for (int pile : piles) hours += (pile + mid - 1) / mid;
            if (hours <= h) answer = mid, high = mid - 1;
            else low = mid + 1;
        }
        return answer;
    }
};
